function GrupoTabla({ titulo, filas, editMode, onChange, onDelete, onAdd }) {
  return (
    <div style={{ ...cardStyle, padding: "16px 18px", flex: "1 1 340px" }}>
      <div style={{ fontSize: 13, color: "#f2c230", fontWeight: 600, marginBottom: 12, letterSpacing: 0.4 }}>
        {titulo}
      </div>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
        <thead>
          <tr style={{ color: "#6b6b68", textAlign: "left" }}>
            <th style={{ fontWeight: 400, paddingBottom: 8, width: 46 }}>Tiempo</th>
            <th style={{ fontWeight: 400, paddingBottom: 8 }}>Contenido</th>
            <th style={{ fontWeight: 400, paddingBottom: 8 }}>Explicación</th>
            <th style={{ fontWeight: 400, paddingBottom: 8, width: 90 }}>Sector</th>
            {editMode && <th style={{ width: 20 }} />}
          </tr>
        </thead>
        <tbody>
          {filas.map((f, i) =>
            editMode ? (
              <tr key={i} style={{ borderTop: "1px solid #232324" }}>
                <td style={{ padding: "9px 8px 9px 0", verticalAlign: "top" }}>
                  <input style={editInputStyle} value={f.t} onChange={(e) => onChange(i, "t", e.target.value)} />
                </td>
                <td style={{ padding: "9px 8px 9px 0", verticalAlign: "top" }}>
                  <input style={editInputStyle} value={f.c} onChange={(e) => onChange(i, "c", e.target.value)} />
                </td>
                <td style={{ padding: "9px 8px 9px 0", verticalAlign: "top" }}>
                  <input style={editInputStyle} value={f.e} onChange={(e) => onChange(i, "e", e.target.value)} />
                </td>
                <td style={{ padding: "9px 8px 9px 0", verticalAlign: "top" }}>
                  <input style={editInputStyle} value={f.s} onChange={(e) => onChange(i, "s", e.target.value)} />
                </td>
                <td style={{ padding: "9px 0", verticalAlign: "top" }}>
                  <button
                    onClick={() => onDelete(i)}
                    style={{ background: "transparent", border: "none", color: "#6b6b68", cursor: "pointer", fontSize: 14 }}
                    title="Eliminar fila"
                  >
                    ×
                  </button>
                </td>
              </tr>
            ) : (
              <tr key={i} style={{ borderTop: "1px solid #232324" }}>
                <td style={{ padding: "9px 8px 9px 0", color: "#f5f4f0", fontWeight: 600, verticalAlign: "top" }}>{f.t}</td>
                <td style={{ padding: "9px 8px 9px 0", color: "#f5f4f0", fontWeight: 500, verticalAlign: "top" }}>{f.c}</td>
                <td style={{ padding: "9px 8px 9px 0", color: "#8f8f8c", verticalAlign: "top" }}>{f.e}</td>
                <td style={{ padding: "9px 0", verticalAlign: "top" }}>
                  <span style={tagStyle}>{f.s}</span>
                </td>
              </tr>
            )
          )}
        </tbody>
      </table>
      {editMode && (
        <button
          onClick={onAdd}
          style={{
            ...pillButton,
            marginTop: 12,
            background: "transparent",
            border: "1px dashed #2a2a2c",
            color: "#8f8f8c",
            width: "100%",
          }}
        >
          + Agregar fila
        </button>
      )}
    </div>
  );
}

function AsistenciaPanel({ perfil }) {
  const fecha = hoyISO();
  const [presentes, setPresentes] = useState({});
  const [cargando, setCargando] = useState(true);
  const [abierto, setAbierto] = useState(false);

  useEffect(() => {
    if (!abierto) return;
    setCargando(true);
    cargarAsistenciaFecha(fecha).then((m) => {
      setPresentes(m);
      setCargando(false);
    });
  }, [abierto]);

  async function marcar(jugadorDbId, presente) {
    setPresentes((prev) => ({ ...prev, [jugadorDbId]: presente }));
    await guardarAsistencia(jugadorDbId, fecha, presente, perfil?.id);
  }

  const jugadoresOrdenados = [...POOL].sort((a, b) => a.id.localeCompare(b.id));
  const totalMarcados = Object.keys(presentes).length;
  const totalPresentes = Object.values(presentes).filter(Boolean).length;

  if (!abierto) {
    return (
      <button
        onClick={() => setAbierto(true)}
        style={{ ...pillButton, marginBottom: 20, background: "transparent", border: "1px dashed #2a2a2c", color: "#8f8f8c" }}
      >
        ✅ Cargar asistencia de hoy
      </button>
    );
  }

  return (
    <div style={{ ...cardStyle, padding: "16px 18px", marginBottom: 20 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
        <div style={{ fontSize: 13, color: "#f5f4f0", fontWeight: 500 }}>Asistencia de hoy</div>
        <button onClick={() => setAbierto(false)} style={{ background: "transparent", border: "none", color: "#6b6b68", fontSize: 12, cursor: "pointer" }}>
          Cerrar
        </button>
      </div>
      <div style={{ fontSize: 11, color: "#8f8f8c", marginBottom: 12 }}>
        {cargando ? "Cargando…" : `${totalPresentes} presentes de ${totalMarcados} marcados · ${jugadoresOrdenados.length} en el plantel`}
      </div>
      {!cargando && (
        <div style={{ maxHeight: 340, overflowY: "auto" }}>
          {jugadoresOrdenados.map((j) => {
            const estado = presentes[j.dbId]; // true, false, o undefined = sin marcar
            return (
              <div
                key={j.dbId}
                style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "7px 0", borderTop: "1px solid #202021" }}
              >
                <span style={{ fontSize: 12.5, color: "#c9c9c6" }}>{j.id}</span>
                <div style={{ display: "flex", gap: 6 }}>
                  <button
                    onClick={() => marcar(j.dbId, true)}
                    style={{
                      ...pillButton, fontSize: 11, padding: "4px 10px",
                      border: "1px solid " + (estado === true ? "#5fbf7a" : "#2a2a2c"),
                      background: estado === true ? "#111a12" : "transparent",
                      color: estado === true ? "#5fbf7a" : "#6b6b68",
                    }}
                  >
                    Presente
                  </button>
                  <button
                    onClick={() => marcar(j.dbId, false)}
                    style={{
                      ...pillButton, fontSize: 11, padding: "4px 10px",
                      border: "1px solid " + (estado === false ? "#e0665c" : "#2a2a2c"),
                      background: estado === false ? "#2a120f" : "transparent",
                      color: estado === false ? "#e0665c" : "#6b6b68",
                    }}
                  >
                    Ausente
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function SesionPage({ perfil }) {
  const [sesiones, setSesiones] = useState(SESIONES_INICIALES);
  const [dia, setDia] = useState("Lunes");
  const [editMode, setEditMode] = useState(false);
  const sesion = sesiones[dia];

  function updateFila(grupo, index, field, value) {
    setSesiones((prev) => {
      const filas = prev[dia][grupo].map((f, i) => (i === index ? { ...f, [field]: value } : f));
      return { ...prev, [dia]: { ...prev[dia], [grupo]: filas } };
    });
  }
  function addFila(grupo) {
    setSesiones((prev) => ({
      ...prev,
      [dia]: { ...prev[dia], [grupo]: [...prev[dia][grupo], { t: "", c: "", e: "", s: "" }] },
    }));
  }
  function deleteFila(grupo, index) {
    setSesiones((prev) => ({
      ...prev,
      [dia]: { ...prev[dia], [grupo]: prev[dia][grupo].filter((_, i) => i !== index) },
    }));
  }

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: 12, marginBottom: 20 }}>
        <div>
          <div style={{ fontSize: 20, color: "#f5f4f0", fontWeight: 500 }}>Sesión del día</div>
          <div style={{ fontSize: 13, color: "#8f8f8c", marginTop: 2 }}>{sesion.fecha}</div>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          {editMode ? (
            <button
              onClick={() => setEditMode(false)}
              style={{ ...pillButton, background: "#f2c230", color: "#141415", border: "none" }}
            >
              Guardar cambios
            </button>
          ) : (
            <button
              onClick={() => setEditMode(true)}
              style={{ ...pillButton, background: "transparent", border: "1px solid #f2c230", color: "#f2c230" }}
            >
              Editar
            </button>
          )}
          <button
            onClick={() => crearNotificacion("sesion_planificada", `🏉 Sesión del ${dia.toLowerCase()} planificada — revisala.`, null, perfil?.id)}
            style={{ ...pillButton, background: "#f2c230", color: "#141415", border: "none" }}
          >
            Avisar al staff
          </button>
        </div>
      </div>

      {puedeGestionar(perfil) && <AsistenciaPanel perfil={perfil} />}

      <div style={{ display: "flex", gap: 8, marginBottom: 20, flexWrap: "wrap" }}>
        {DIAS_SEMANA.map((d) => (
          <button
            key={d}
            onClick={() => setDia(d)}
            style={{
              ...pillButton,
              border: "1px solid " + (dia === d ? "#f2c230" : "#2a2a2c"),
              background: dia === d ? "#1d1a0c" : "transparent",
              color: dia === d ? "#f2c230" : "#c9c9c6",
            }}
          >
            {d}
          </button>
        ))}
      </div>

      <div style={{ fontSize: 11, color: "#6b6b68", letterSpacing: 0.5, marginBottom: 12 }}>{sesion.semana}</div>

      <div style={{ display: "flex", gap: 14, flexWrap: "wrap" }}>
        <GrupoTabla
          titulo="GRUPO 1"
          filas={sesion.grupo1}
          editMode={editMode}
          onChange={(i, field, value) => updateFila("grupo1", i, field, value)}
          onDelete={(i) => deleteFila("grupo1", i)}
          onAdd={() => addFila("grupo1")}
        />
        <GrupoTabla
          titulo="GRUPO 2"
          filas={sesion.grupo2}
          editMode={editMode}
          onChange={(i, field, value) => updateFila("grupo2", i, field, value)}
          onDelete={(i) => deleteFila("grupo2", i)}
          onAdd={() => addFila("grupo2")}
        />
      </div>
    </div>
  );
}

