function GimnasioPage() {
  const [plan, setPlan] = useState(PLAN_GYM_INICIAL);
  const [dia, setDia] = useState("Lunes");
  const [editMode, setEditMode] = useState(false);
  const bloques = plan[dia];

  function updateTitulo(bi, value) {
    setPlan((prev) => {
      const next = prev[dia].map((b, i) => (i === bi ? { ...b, titulo: value } : b));
      return { ...prev, [dia]: next };
    });
  }
  function updateEjercicio(bi, ei, field, value) {
    setPlan((prev) => {
      const next = prev[dia].map((b, i) =>
        i === bi ? { ...b, ejercicios: b.ejercicios.map((e, j) => (j === ei ? { ...e, [field]: value } : e)) } : b
      );
      return { ...prev, [dia]: next };
    });
  }
  function addEjercicio(bi) {
    setPlan((prev) => {
      const next = prev[dia].map((b, i) =>
        i === bi ? { ...b, ejercicios: [...b.ejercicios, { nombre: "", detalle: "", valor: "" }] } : b
      );
      return { ...prev, [dia]: next };
    });
  }
  function deleteEjercicio(bi, ei) {
    setPlan((prev) => {
      const next = prev[dia].map((b, i) => (i === bi ? { ...b, ejercicios: b.ejercicios.filter((_, j) => j !== ei) } : b));
      return { ...prev, [dia]: next };
    });
  }
  function deleteBloque(bi) {
    setPlan((prev) => ({ ...prev, [dia]: prev[dia].filter((_, i) => i !== bi) }));
  }
  function addBloque() {
    setPlan((prev) => ({ ...prev, [dia]: [...prev[dia], { titulo: "NUEVO BLOQUE", ejercicios: [] }] }));
  }

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: 12, marginBottom: 20 }}>
        <div>
          <div style={{ fontSize: 20, color: "#f5f4f0", fontWeight: 500 }}>Plan de gimnasio</div>
          <div style={{ fontSize: 13, color: "#8f8f8c", marginTop: 2 }}>3 estímulos por semana</div>
        </div>
        {editMode ? (
          <button
            onClick={() => setEditMode(false)}
            style={{ ...pillButton, background: "#f2c230", color: "#141415", border: "none" }}
          >
            Guardar cambios
          </button>
        ) : (
          <button
            onClick={() => setEditMode(true)}
            style={{ ...pillButton, background: "transparent", border: "1px solid #f2c230", color: "#f2c230" }}
          >
            Editar
          </button>
        )}
      </div>

      <div style={{ display: "flex", gap: 8, marginBottom: 20, flexWrap: "wrap" }}>
        {DIAS_GYM.map((d) => (
          <button
            key={d}
            onClick={() => setDia(d)}
            style={{
              ...pillButton,
              border: "1px solid " + (dia === d ? "#f2c230" : "#2a2a2c"),
              background: dia === d ? "#1d1a0c" : "transparent",
              color: dia === d ? "#f2c230" : "#c9c9c6",
            }}
          >
            {d}
          </button>
        ))}
      </div>

      {bloques.map((b, bi) => (
        <BloqueGym
          key={bi}
          bloque={b}
          editMode={editMode}
          onChangeTitulo={(v) => updateTitulo(bi, v)}
          onChangeEjercicio={(ei, field, v) => updateEjercicio(bi, ei, field, v)}
          onDeleteEjercicio={(ei) => deleteEjercicio(bi, ei)}
          onAddEjercicio={() => addEjercicio(bi)}
          onDeleteBloque={() => deleteBloque(bi)}
        />
      ))}

      {editMode && (
        <button
          onClick={addBloque}
          style={{ ...pillButton, background: "transparent", border: "1px dashed #2a2a2c", color: "#8f8f8c", width: "100%" }}
        >
          + Agregar bloque
        </button>
      )}
    </div>
  );
}

// Plantel único del club — los mismos jugadores rotan entre Superior e Intermedia según la semana.
const POSICIONES_ALT = {
  "Primera línea": ["Hooker", "Segunda línea"],
  Hooker: ["Primera línea", "Tercera línea"],
  "Segunda línea": ["Tercera línea", "Primera línea"],
  "Tercera línea": ["Segunda línea", "Centro"],
  "Medio scrum": ["Apertura", "Wing"],
  Apertura: ["Medio scrum", "Centro"],
  Centro: ["Wing", "Apertura"],
  Wing: ["Fullback", "Centro"],
  Fullback: ["Wing", "Apertura"],
};

// Altura y peso salen de datos que cargaría cada jugador al registrarse — acá los derivamos
// de forma determinística según el puesto para tener valores de prueba realistas.
const RANGOS_FISICOS = {
  "Primera línea": { altura: [178, 188], peso: [105, 118] },
  Hooker: { altura: [176, 184], peso: [98, 108] },
  "Segunda línea": { altura: [194, 203], peso: [108, 118] },
  "Tercera línea": { altura: [186, 196], peso: [95, 108] },
  "Medio scrum": { altura: [170, 178], peso: [78, 86] },
  Apertura: { altura: [178, 186], peso: [82, 90] },
  Centro: { altura: [180, 188], peso: [88, 96] },
  Wing: { altura: [176, 186], peso: [82, 92] },
  Fullback: { altura: [178, 188], peso: [84, 92] },
};

function datosFisicos(puesto, nombre) {
  const seed = [...(nombre || "?")].reduce((a, c) => a + c.charCodeAt(0), 0);
  const r = RANGOS_FISICOS[puesto] || RANGOS_FISICOS["Centro"];
  const altura = r.altura[0] + (seed % (r.altura[1] - r.altura[0] + 1));
  const peso = r.peso[0] + ((seed * 7) % (r.peso[1] - r.peso[0] + 1));
  return { altura, peso };
}

