const ROLES_REGISTRO = ["Jugador", "Cuerpo técnico", "Manager", "Cuerpo médico"];

// Gestión general (resultados de partidos, plantel): Cuerpo técnico y Manager.
function puedeGestionar(perfil) {
  return !!perfil && (perfil.rol === "Cuerpo técnico" || perfil.rol === "Manager");
}
// Trabajo técnico específico (formaciones, GPS, VEO, informe de partido): solo Cuerpo técnico.
function esEntrenador(perfil) {
  return !!perfil && perfil.rol === "Cuerpo técnico";
}
// Herramientas internas del club (staff, escudos, GPS·ACWR, evaluaciones, métricas): todo el staff.
function esStaff(perfil) {
  return !!perfil && ["Cuerpo técnico", "Cuerpo médico", "Manager"].includes(perfil.rol);
}

function LoginPage() {
  const [modo, setModo] = useState("ingresar"); // "ingresar" | "registro"
  const [rol, setRol] = useState("Jugador");
  const [jugadoresLista, setJugadoresLista] = useState([]);
  const [jugadorId, setJugadorId] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [password2, setPassword2] = useState("");
  const [nombreCompleto, setNombreCompleto] = useState("");
  const [usuario, setUsuario] = useState("");
  const [altura, setAltura] = useState("");
  const [peso, setPeso] = useState("");
  const [soyNuevo, setSoyNuevo] = useState(false);
  const [nombreNuevoJugador, setNombreNuevoJugador] = useState("");
  const [posicionNueva, setPosicionNueva] = useState("Centro");
  const [mensaje, setMensaje] = useState("");
  const [cargando, setCargando] = useState(false);

  useEffect(() => {
    // Lista pública de jugadores para el selector de registro — no requiere estar logueado.
    supabase
      .from("jugadores")
      .select("id, nombre")
      .order("nombre")
      .then(({ data, error }) => {
        if (!error && data) {
          setJugadoresLista(data);
          if (data.length) setJugadorId(data[0].nombre);
        }
      });
  }, []);

  async function handleIngresar() {
    setMensaje("");
    setCargando(true);
    const { error } = await supabase.auth.signInWithPassword({ email, password });
    setCargando(false);
    if (error) setMensaje(error.message);
    // Si no hay error, el listener de sesión en AppRoot te lleva solo al HUB.
  }

  async function handleRegistro() {
    setMensaje("");
    if (password !== password2) {
      setMensaje("Las contraseñas no coinciden.");
      return;
    }
    setCargando(true);

    const nombreFinal = rol === "Jugador" ? (soyNuevo ? nombreNuevoJugador : jugadorId) : nombreCompleto;
    const jugadorDb = jugadoresLista.find((j) => j.nombre === jugadorId);

    // Mandamos todo como metadata del usuario: así el perfil se crea solo del lado del servidor
    // (un trigger en la base), sin depender de que el navegador ya tenga sesión activa en este
    // instante — que es justo lo que fallaba si el proyecto pide confirmar el email antes de entrar.
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          nombre: nombreFinal,
          usuario,
          rol,
          jugador_id: rol === "Jugador" && !soyNuevo ? jugadorDb?.id || "" : "",
          nombre_nuevo_jugador: rol === "Jugador" && soyNuevo ? nombreNuevoJugador : "",
          posicion_nueva: rol === "Jugador" && soyNuevo ? posicionNueva : "",
          altura: rol === "Jugador" ? altura : "",
          peso: rol === "Jugador" ? peso : "",
        },
      },
    });
    setCargando(false);
    if (error) {
      setMensaje(error.message);
      return;
    }

    if (!data.session) {
      setMensaje("¡Cuenta creada! Revisá tu email para confirmarla y después iniciá sesión.");
      setModo("ingresar");
    }
    // Si Supabase ya devolvió sesión activa, el listener en AppRoot te lleva directo al HUB.
  }

  return (
    <div
      style={{
        minHeight: 620,
        background: "#0b0b0c",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: "40px 16px",
        fontFamily: "'Inter', sans-serif",
      }}
    >
      <style>{FONTS}</style>
      <div style={{ width: "100%", maxWidth: 400 }}>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginBottom: 24 }}>
          <Shield size={40} />
          <div
            style={{
              marginTop: 10,
              fontFamily: "'Oswald', sans-serif",
              fontWeight: 600,
              fontSize: 18,
              letterSpacing: 0.5,
              color: "#f5f4f0",
            }}
          >
            Obras <span style={{ color: "#f2c230" }}>Rugby Hub</span>
          </div>
          <div style={{ width: 36, height: 2, background: "#f2c230", marginTop: 10 }} />
        </div>

        <div style={{ background: "#141415", border: "1px solid #262627", borderRadius: 10, padding: "26px 26px" }}>
          <div style={{ display: "flex", gap: 8, marginBottom: 22 }}>
            <button
              onClick={() => {
                setModo("ingresar");
                setMensaje("");
              }}
              style={{
                ...pillButton,
                flex: 1,
                border: "1px solid " + (modo === "ingresar" ? "#f2c230" : "#2a2a2c"),
                background: modo === "ingresar" ? "#1d1a0c" : "transparent",
                color: modo === "ingresar" ? "#f2c230" : "#c9c9c6",
              }}
            >
              Ingresar
            </button>
            <button
              onClick={() => {
                setModo("registro");
                setMensaje("");
              }}
              style={{
                ...pillButton,
                flex: 1,
                border: "1px solid " + (modo === "registro" ? "#f2c230" : "#2a2a2c"),
                background: modo === "registro" ? "#1d1a0c" : "transparent",
                color: modo === "registro" ? "#f2c230" : "#c9c9c6",
              }}
            >
              Crear cuenta
            </button>
          </div>

          {modo === "ingresar" ? (
            <div>
              <label style={labelStyle}>Email</label>
              <input style={inputStyle} type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="tu@email.com" />
              <label style={labelStyle}>Contraseña</label>
              <input type="password" style={inputStyle} value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" />
              {mensaje && <div style={{ color: "#e0665c", fontSize: 12.5, marginTop: 10 }}>{mensaje}</div>}
              <button type="button" onClick={handleIngresar} disabled={cargando} style={buttonStyle}>
                {cargando ? "Ingresando…" : "Ingresar"}
              </button>
            </div>
          ) : (
            <div>
              <label style={labelStyle}>¿Quién sos?</label>
              <select value={rol} onChange={(e) => setRol(e.target.value)} style={inputStyle}>
                {ROLES_REGISTRO.map((r) => (
                  <option key={r} value={r} style={{ background: "#0e0e0f" }}>
                    {r}
                  </option>
                ))}
              </select>

              {rol === "Jugador" && (
                <>
                  <div style={{ display: "flex", gap: 8, margin: "6px 0 4px" }}>
                    <button
                      type="button"
                      onClick={() => setSoyNuevo(false)}
                      style={{
                        ...pillButton, flex: 1, fontSize: 12,
                        border: "1px solid " + (!soyNuevo ? "#f2c230" : "#2a2a2c"),
                        background: !soyNuevo ? "#1d1a0c" : "transparent",
                        color: !soyNuevo ? "#f2c230" : "#c9c9c6",
                      }}
                    >
                      Estoy en la lista
                    </button>
                    <button
                      type="button"
                      onClick={() => setSoyNuevo(true)}
                      style={{
                        ...pillButton, flex: 1, fontSize: 12,
                        border: "1px solid " + (soyNuevo ? "#f2c230" : "#2a2a2c"),
                        background: soyNuevo ? "#1d1a0c" : "transparent",
                        color: soyNuevo ? "#f2c230" : "#c9c9c6",
                      }}
                    >
                      Soy nuevo
                    </button>
                  </div>

                  {!soyNuevo ? (
                    <>
                      <label style={labelStyle}>Elegí tu nombre</label>
                      <select value={jugadorId} onChange={(e) => setJugadorId(e.target.value)} style={inputStyle}>
                        {jugadoresLista.map((j) => (
                          <option key={j.id} value={j.nombre} style={{ background: "#0e0e0f" }}>
                            {j.nombre}
                          </option>
                        ))}
                      </select>
                    </>
                  ) : (
                    <>
                      <label style={labelStyle}>Nombre y apellido</label>
                      <input style={inputStyle} value={nombreNuevoJugador} onChange={(e) => setNombreNuevoJugador(e.target.value)} placeholder="Nombre y apellido" />
                      <label style={labelStyle}>Posición ideal</label>
                      <select value={posicionNueva} onChange={(e) => setPosicionNueva(e.target.value)} style={inputStyle}>
                        {Object.keys(POSICIONES_ALT).map((p) => (
                          <option key={p} value={p} style={{ background: "#0e0e0f" }}>
                            {p}
                          </option>
                        ))}
                      </select>
                    </>
                  )}
                  <label style={labelStyle}>Altura (cm)</label>
                  <input style={inputStyle} value={altura} onChange={(e) => setAltura(e.target.value)} placeholder="ej: 182" />
                  <label style={labelStyle}>Peso (kg)</label>
                  <input style={inputStyle} value={peso} onChange={(e) => setPeso(e.target.value)} placeholder="ej: 88" />
                </>
              )}
              {rol !== "Jugador" && (
                <>
                  <label style={labelStyle}>Nombre y apellido</label>
                  <input style={inputStyle} value={nombreCompleto} onChange={(e) => setNombreCompleto(e.target.value)} placeholder="Nombre y apellido" />
                </>
              )}

              <label style={labelStyle}>Usuario (para mostrar en el HUB)</label>
              <input style={inputStyle} value={usuario} onChange={(e) => setUsuario(e.target.value)} placeholder="usuario" />
              <label style={labelStyle}>Email</label>
              <input style={inputStyle} type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="tu@email.com" />
              <label style={labelStyle}>Contraseña</label>
              <input type="password" style={inputStyle} value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Mínimo 6 caracteres" />
              <label style={labelStyle}>Repetir contraseña</label>
              <input type="password" style={inputStyle} value={password2} onChange={(e) => setPassword2(e.target.value)} />

              {mensaje && <div style={{ color: mensaje.startsWith("¡Cuenta") ? "#5fbf7a" : "#e0665c", fontSize: 12.5, marginTop: 10 }}>{mensaje}</div>}
              <button type="button" onClick={handleRegistro} disabled={cargando} style={buttonStyle}>
                {cargando ? "Creando…" : "Crear mi cuenta"}
              </button>
            </div>
          )}
        </div>

        <div style={{ textAlign: "center", fontSize: 11, color: "#5a5a58", marginTop: 18 }}>
          Obras Rugby Hub · datos del club
        </div>
      </div>
    </div>
  );
}

let ESCUDOS_RIVALES = {}; // nombre de club -> url del escudo real subido a Supabase Storage
let TEMPORADA_ACTIVA = "2026"; // se sobreescribe con el valor real de la base al cargar

// Crea una notificación in-app. roles null = la ven todos; si no, solo esos roles.
async function crearNotificacion(tipo, mensaje, roles, creadoPor) {
  const { error } = await supabase
    .from("notificaciones")
    .insert({ tipo, mensaje, roles_destino: roles || null, creado_por: creadoPor || null });
  if (error) console.error("Error creando notificación:", error);
}

async function cargarEscudos() {
  const { data, error } = await supabase.from("equipos_rivales").select("nombre, escudo_url");
  if (error) {
    console.error("Error cargando escudos:", error);
    return;
  }
  ESCUDOS_RIVALES = Object.fromEntries((data || []).filter((r) => r.escudo_url).map((r) => [r.nombre, r.escudo_url]));
}

async function cargarConfig() {
  const { data, error } = await supabase.from("config").select("clave, valor").eq("clave", "temporada_activa").maybeSingle();
  if (!error && data?.valor) TEMPORADA_ACTIVA = String(data.valor);
}

let EVALUACIONES_REALES = {}; // nombre de jugador -> última evaluación real cargada por el cuerpo técnico

async function cargarEvaluaciones() {
  const { data, error } = await supabase
    .from("evaluaciones")
    .select("fecha, potencia, reactividad, fuerza, velocidad, resistencia, jugadores(nombre)")
    .order("fecha", { ascending: false });
  if (error) {
    console.error("Error cargando evaluaciones:", error);
    return;
  }
  const porNombre = {};
  (data || []).forEach((r) => {
    const nombre = r.jugadores?.nombre;
    if (!nombre || porNombre[nombre]) return; // ya tenemos la más nueva de ese jugador (viene ordenado desc)
    porNombre[nombre] = {
      fecha: r.fecha,
      Potencia: r.potencia,
      Reactividad: r.reactividad,
      Fuerza: r.fuerza,
      Velocidad: r.velocidad,
      Resistencia: r.resistencia,
    };
  });
  EVALUACIONES_REALES = porNombre;
}

async function cargarTodo() {
  await Promise.all([cargarJugadores(), cargarCalendario(), cargarFormaciones(), cargarEscudos(), cargarConfig(), cargarEvaluaciones()]);
}

